{"command":"cat <<'EOF' > src/main.rs
use clap::Parser;
use std::{io, time::{Duration, Instant}};
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    widgets::{Block, Borders, Paragraph},
    Terminal,
};

#[derive(Parser, Debug)]
#[clap(name = "thokr", version = "0.4.1", about = "sleek typing tui with visualized results and historical logging")]
struct Args {
    #[clap(short = 'f', long, help = "number of sentences to use in test")]
    full_sentences: Option<usize>,

    #[clap(short = 'l', long, default_value = "english", help = "language to pull words from")]
    supported_language: String,

    #[clap(short = 'p', long, help = "custom prompt to use")]
    prompt: Option<String>,

    #[clap(short = 's', long, help = "number of seconds to run test")]
    number_of_secs: Option<usize>,

    #[clap(short = 'w', long, default_value = "15", help = "number of words to use in test")]
    number_of_words: usize,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Run the app
    let res = run_app(&mut terminal, args);

    // Restore terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err);
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, args: Args) -> io::Result<()> {
    loop {
        terminal.draw(|f| {
            let size = f.size();
            let block = Block::default().title("thokr").borders(Borders::ALL);
            f.render_widget(block, size);
        })?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if let KeyCode::Char('q') = key.code {
                    return Ok(());
                }
            }
        }
    }
}
EOF
"}

