{"command":"cat <<'EOF' > src/words.rs
pub const ENGLISH: &str = include_str!("../english.txt");
pub const ENGLISH1K: &str = include_str!("../english1k.txt");
pub const ENGLISH10K: &str = include_str!("../english10k.txt");
pub const SENTENCES: &str = include_str!("../sentences.txt");

use rand::seq::SliceRandom;

pub fn get_words(lang: &str, count: usize) -> Vec<String> {
    let list = match lang {
        "english1k" => ENGLISH1K,
        "english10k" => ENGLISH10K,
        _ => ENGLISH,
    };
    let mut words: Vec<String> = list.lines().map(|s| s.to_string()).collect();
    let mut rng = rand::thread_rng();
    words.shuffle(&mut rng);
    words.into_iter().take(count).collect()
}

pub fn get_sentences(count: usize) -> Vec<String> {
    let all_words: Vec<&str> = SENTENCES.lines().collect();
    let mut rng = rand::thread_rng();
    let mut sentences = Vec::new();

    // We don't know the exact grammar, but we can try to mimic it.
    // Based on earlier observation, many start with "The" or a capitalized word.
    for _ in 0..count {
        let len = *[3, 4, 5, 6, 7, 8].choose(&mut rng).unwrap();
        let mut s = Vec::new();
        for _ in 0..len {
            s.push((*all_words.choose(&mut rng).unwrap()).to_string());
        }
        let mut sentence = s.join(" ");
        // Capitalize first letter and add a period
        let mut chars = sentence.chars();
        sentence = match chars.next() {
            None => String::new(),
            Some(f) => f.to_uppercase().collect::<String>() + chars.as_str() + ".",
        };
        sentences.push(sentence);
    }
    sentences
}
EOF
"}

