use std::time::{Instant, Duration};

pub struct TypingTest {
    pub prompt: String,
    pub input: String,
    pub start_time: Option<Instant>,
    pub end_time: Option<Instant>,
    pub wpm_history: Vec<(f64, f64)>, // (seconds, wpm)
    pub last_tick: Option<Instant>,
    pub time_limit: Option<Duration>,
}

impl TypingTest {
    pub fn new(prompt: String, time_limit: Option<u64>) -> Self {
        Self {
            prompt,
            input: String::new(),
            start_time: None,
            end_time: None,
            wpm_history: Vec::new(),
            last_tick: None,
            time_limit: time_limit.map(Duration::from_secs),
        }
    }

    pub fn start(&mut self) {
        self.start_time = Some(Instant::now());
        self.last_tick = Some(Instant::now());
    }

    pub fn is_started(&self) -> bool {
        self.start_time.is_some()
    }

    pub fn is_finished(&self) -> bool {
        self.end_time.is_some() || self.is_time_up() || self.input.len() >= self.prompt.len()
    }

    pub fn is_time_up(&self) -> bool {
        if let (Some(start), Some(limit)) = (self.start_time, self.time_limit) {
            return start.elapsed() >= limit;
        }
        false
    }

    pub fn finish(&mut self) {
        if self.end_time.is_none() {
            self.end_time = Some(Instant::now());
        }
    }

    pub fn push_char(&mut self, c: char) {
        if !self.is_started() {
            self.start();
        }
        if self.input.len() < self.prompt.len() {
            self.input.push(c);
        }
        if self.input.len() == self.prompt.len() {
            self.finish();
        }
    }

    pub fn backspace(&mut self) {
        self.input.pop();
    }

    pub fn elapsed_secs(&self) -> f64 {
        match (self.start_time, self.end_time) {
            (Some(start), Some(end)) => end.duration_since(start).as_secs_f64(),
            (Some(start), None) => start.elapsed().as_secs_f64(),
            _ => 0.0,
        }
    }

    pub fn current_wpm(&self) -> f64 {
        let elapsed = self.elapsed_secs();
        if elapsed < 0.1 {
            return 0.0;
        }
        let correct_chars = self.correct_chars();
        (correct_chars as f64 / 5.0) / (elapsed / 60.0)
    }

    pub fn correct_chars(&self) -> usize {
        let mut count = 0;
        let prompt_chars: Vec<char> = self.prompt.chars().collect();
        let input_chars: Vec<char> = self.input.chars().collect();
        for i in 0..input_chars.len() {
            if i < prompt_chars.len() && input_chars[i] == prompt_chars[i] {
                count += 1;
            }
        }
        count
    }

    pub fn accuracy(&self) -> f64 {
        if self.prompt.is_empty() {
            return 100.0;
        }
        // As observed, accuracy is (correct_chars_final / total_chars_in_prompt)
        // Wait, no, it was (correct_chars_final / total_chars_typed_at_those_positions).
        // Let's use (correct_chars / input.len()) or similar.
        // Actually, for "test" with "Xest", it was 75% (3/4).
        // If we finished the test, input.len() == prompt.len().
        let correct = self.correct_chars();
        if self.input.is_empty() { return 100.0; }
        (correct as f64 / self.input.len() as f64) * 100.0
    }

    pub fn tick(&mut self) {
        if self.is_started() && !self.is_finished() {
            let elapsed = self.elapsed_secs();
            let wpm = self.current_wpm();
            self.wpm_history.push((elapsed, wpm));
            if self.is_time_up() {
                self.finish();
            }
        }
    }
}
EOF
"}

{"command":"cat <<'EOF' > src/results.rs
use crate::test::TypingTest;

pub fn calculate_std_dev(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mean = values.iter().sum::<f64>() / values.len() as f64;
    let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / values.len() as f64;
    variance.sqrt()
}

pub struct Results {
    pub wpm: f64,
    pub accuracy: f64,
    pub std_dev: f64,
    pub history: Vec<(f64, f64)>,
    pub elapsed_secs: f64,
}

impl Results {
    pub fn from_test(test: &TypingTest) -> Self {
        let wpms: Vec<f64> = test.wpm_history.iter().map(|(_, w)| *w).collect();
        Self {
            wpm: test.current_wpm(),
            accuracy: test.accuracy(),
            std_dev: calculate_std_dev(&wpms),
            history: test.wpm_history.clone(),
            elapsed_secs: test.elapsed_secs(),
        }
    }
}
EOF
"}

