{"command":"cat <<'EOF' > src/logging.rs
use std::fs::{OpenOptions, create_dir_all};
use std::io::Write;
use chrono::Local;
use crate::results::Results;

pub fn log_result(num_words: usize, num_secs: Option<usize>, results: &Results) {
    let config_dir = dirs::config_dir().map(|p| p.join("thokr"));
    if let Some(path) = config_dir {
        if create_dir_all(&path).is_ok() {
            let log_path = path.join("log.csv");
            let file_exists = log_path.exists();
            if let Ok(mut file) = OpenOptions::new()
                .create(true)
                .append(true)
                .open(log_path)
            {
                if !file_exists {
                    writeln!(file, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev").unwrap();
                }
                let now = Local::now();
                let date_str = now.format("%a %b %d %H:%M:%S %Y").to_string();
                let num_secs_str = num_secs.map(|s| s.to_string()).unwrap_or_default();
                let wpm_str = if results.wpm.is_infinite() { "inf".to_string() } else { format!("{:.0}", results.wpm) };

                writeln!(file, "{},{},{},{:.2},{},{:.0},{:.2}",
                    date_str,
                    num_words,
                    num_secs_str,
                    results.elapsed_secs,
                    wpm_str,
                    results.accuracy,
                    results.std_dev
                ).unwrap();
            }
        }
    }
}
EOF
"}

