{"command":"cat <<'EOF' > src/main.rs
mod words;
mod test;
mod results;
mod logging;

use clap::Parser;
use std::{io, time::{Duration, Instant}};
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, Chart, Axis, Dataset, GraphType},
    Terminal,
};
use crate::test::TypingTest;
use crate::results::Results;

#[derive(Parser, Debug, Clone)]
#[clap(name = "thokr", version = "0.4.1", about = "sleek typing tui with visualized results and historical logging")]
pub struct Args {
    #[clap(short = 'f', long, help = "number of sentences to use in test")]
    full_sentences: Option<usize>,

    #[clap(short = 'l', long, default_value = "english", help = "language to pull words from")]
    supported_language: String,

    #[clap(short = 'p', long, help = "custom prompt to use")]
    prompt: Option<String>,

    #[clap(short = 's', long, help = "number of seconds to run test")]
    number_of_secs: Option<usize>,

    #[clap(short = 'w', long, default_value = "15", help = "number of words to use in test")]
    number_of_words: usize,
}

enum AppState {
    Testing(TypingTest),
    Results(Results, TypingTest),
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = run_app(&mut terminal, args);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err);
    }

    Ok(())
}

fn generate_prompt(args: &Args) -> String {
    if let Some(p) = &args.prompt {
        p.clone()
    } else if let Some(f) = args.full_sentences {
        words::get_sentences(f).join(" ")
    } else {
        words::get_words(&args.supported_language, args.number_of_words).join(" ")
    }
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, args: Args) -> io::Result<()> {
    let mut current_prompt = generate_prompt(&args);
    let mut state = AppState::Testing(TypingTest::new(current_prompt.clone(), args.number_of_secs.map(|s| s as u64)));
    let mut last_tick = Instant::now();

    loop {
        terminal.draw(|f| ui(f, &state))?;

        let timeout = Duration::from_millis(10);
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                match &mut state {
                    AppState::Testing(test) => {
                        match key.code {
                            KeyCode::Esc => return Ok(()),
                            KeyCode::Backspace => test.backspace(),
                            KeyCode::Char(c) => {
                                if key.modifiers.contains(KeyModifiers::CONTROL) && c == 'c' {
                                    return Ok(());
                                }
                                test.push_char(c);
                                if test.is_finished() {
                                    test.finish();
                                    let results = Results::from_test(test);
                                    logging::log_result(args.number_of_words, args.number_of_secs, &results);
                                    state = AppState::Results(results, test.clone());
                                }
                            }
                            KeyCode::Left => {
                                state = AppState::Testing(TypingTest::new(current_prompt.clone(), args.number_of_secs.map(|s| s as u64)));
                            }
                            KeyCode::Right => {
                                current_prompt = generate_prompt(&args);
                                state = AppState::Testing(TypingTest::new(current_prompt.clone(), args.number_of_secs.map(|s| s as u64)));
                            }
                            _ => {}
                        }
                    }
                    AppState::Results(_, test) => {
                        match key.code {
                            KeyCode::Esc => return Ok(()),
                            KeyCode::Char('r') => {
                                state = AppState::Testing(TypingTest::new(current_prompt.clone(), args.number_of_secs.map(|s| s as u64)));
                            }
                            KeyCode::Char('n') => {
                                current_prompt = generate_prompt(&args);
                                state = AppState::Testing(TypingTest::new(current_prompt.clone(), args.number_of_secs.map(|s| s as u64)));
                            }
                            _ => {}
                        }
                    }
                }
            }
        }

        if let AppState::Testing(test) = &mut state {
            if last_tick.elapsed() >= Duration::from_millis(100) {
                test.tick();
                if test.is_finished() {
                    test.finish();
                    let results = Results::from_test(test);
                    logging::log_result(args.number_of_words, args.number_of_secs, &results);
                    state = AppState::Results(results, test.clone());
                }
                last_tick = Instant::now();
            }
        }
    }
}

fn ui(f: &mut ratatui::Frame, state: &AppState) {
    let size = f.size();

    match state {
        AppState::Testing(test) => {
            let layout = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Percentage(40),
                    Constraint::Percentage(20),
                    Constraint::Percentage(40),
                ])
                .split(size);

            let mut spans = Vec::new();
            let prompt_chars: Vec<char> = test.prompt.chars().collect();
            let input_chars: Vec<char> = test.input.chars().collect();

            for i in 0..prompt_chars.len() {
                if i < input_chars.len() {
                    if input_chars[i] == prompt_chars[i] {
                        spans.push(Span::styled(
                            prompt_chars[i].to_string(),
                            Style::default().fg(Color::Indexed(2)).add_modifier(Modifier::BOLD),
                        ));
                    } else {
                        spans.push(Span::styled(
                            prompt_chars[i].to_string(),
                            Style::default().fg(Color::Indexed(1)).add_modifier(Modifier::BOLD),
                        ));
                    }
                } else if i == input_chars.len() {
                    spans.push(Span::styled(
                        prompt_chars[i].to_string(),
                        Style::default().add_modifier(Modifier::DIM | Modifier::UNDERLINED),
                    ));
                } else {
                    spans.push(Span::styled(
                        prompt_chars[i].to_string(),
                        Style::default().add_modifier(Modifier::BOLD | Modifier::DIM),
                    ));
                }
            }

            let paragraph = Paragraph::new(Line::from(spans))
                .alignment(Alignment::Center)
                .wrap(ratatui::widgets::Wrap { trim: true });
            f.render_widget(paragraph, layout[1]);
        }
        AppState::Results(res, _) => {
            let layout = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(1),
                    Constraint::Min(10),
                    Constraint::Length(1),
                    Constraint::Length(1),
                    Constraint::Length(1),
                    Constraint::Length(1),
                ])
                .split(size);

            let history_data: Vec<(f64, f64)> = res.history.iter().cloned().collect();
            let max_wpm = history_data.iter().map(|(_, w)| *w).fold(0.0, f64::max);
            let max_secs = history_data.iter().map(|(s, _)| *s).fold(0.0, f64::max);

            let datasets = vec![Dataset::default()
                .marker(ratatui::symbols::Marker::Braille)
                .graph_type(GraphType::Line)
                .style(Style::default().fg(Color::White))
                .data(&history_data)];

            let chart = Chart::new(datasets)
                .block(Block::default())
                .x_axis(
                    Axis::default()
                        .title("seconds")
                        .style(Style::default().fg(Color::Gray))
                        .bounds([0.0, max_secs])
                        .labels(vec![
                            Span::styled("1", Style::default().add_modifier(Modifier::BOLD)),
                            Span::styled(format!("{:.2}", max_secs), Style::default().add_modifier(Modifier::BOLD)),
                        ]),
                )
                .y_axis(
                    Axis::default()
                        .title("wpm")
                        .style(Style::default().fg(Color::Gray))
                        .bounds([0.0, max_wpm])
                        .labels(vec![
                            Span::styled("0", Style::default().add_modifier(Modifier::BOLD)),
                            Span::styled(format!("{:.0}", max_wpm), Style::default().add_modifier(Modifier::BOLD)),
                        ]),
                );

            // Centering the chart
            let chart_layout = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Percentage(10),
                    Constraint::Percentage(80),
                    Constraint::Percentage(10),
                ])
                .split(layout[1]);

            f.render_widget(chart, chart_layout[1]);

            let wpm_str = if res.wpm.is_infinite() { "inf".to_string() } else { format!("{:.0}", res.wpm) };
            let stats = format!("{} wpm   {:.0}% acc   {:.2} sd", wpm_str, res.accuracy, res.std_dev);
            let stats_para = Paragraph::new(Span::styled(stats, Style::default().add_modifier(Modifier::BOLD)))
                .alignment(Alignment::Center);
            f.render_widget(stats_para, layout[3]);

            let help = Paragraph::new(Span::styled("(r)etry / (n)ew / (esc)ape", Style::default().add_modifier(Modifier::ITALIC)))
                .alignment(Alignment::Center);
            f.render_widget(help, layout[5]);
        }
    }
}
EOF
"}

